begin;

do $$
begin
  if exists (select 1 from assignment) then
    raise exception 'There are already assignments. Delete them first (delete from assignment;) to load these again.';
  end if;
end $$;

update student_group set subgroups = 2 where subgroups < 2 and name in ('AI-231', 'CR-231', 'IBM-251');


-- Result: the number of assignments loaded
select count(*) as assignments, 941 as expected from assignment;

